INSERT INTO public.auditlog_logentry VALUES (1129, '1', 1, 'Policy object (1)', 0, '{"id": ["None", "1"], "body": ["None", "<p><p></p></p><h3 style=\"text-align: center; \"><strong><u>Code of Conduct Policy</u></strong></h3><p><strong>Purpose:</strong><br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;To set expectations for professional behavior and ensure a respectful and ethical workplace.</p><p><strong>Body:</strong><br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; All employees must adhere to the highest standards of ethical conduct in their professional relationships with clients, colleagues, and stakeholders. This includes honesty, integrity, and compliance with company regulations. Harassment, discrimination, and unethical behavior will not be tolerated and may lead to disciplinary actions, including termination. Employees are also expected to maintain confidentiality and avoid conflicts of interest.</p>"], "title": ["None", "Code Policy"], "is_active": ["None", "True"], "created_at": ["None", "2024-09-21 05:28:42.996000"], "created_by": ["None", "1"], "modified_by": ["None", "1"], "is_visible_to_all": ["None", "True"]}', '2026-02-23 12:19:24.029171+05:30', NULL, 58, '127.0.0.1', NULL, NULL, NULL, '', NULL, NULL);
