INSERT INTO public.auditlog_logentry VALUES (1133, '3', 3, 'Policy object (3)', 0, '{"id": ["None", "3"], "body": ["None", "<h3 style=\"text-align: center; \"><strong>Remote Work Policy</strong></h3><p><strong>Purpose:</strong><br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; To provide guidelines for employees working remotely and maintain productivity and communication standards.</p><p><strong>Body:</strong><br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Employees working remotely are expected to maintain regular working hours, be available for meetings, and ensure clear communication with their teams. All company-owned devices should be used with appropriate security measures, including VPNs and updated antivirus software. Any work-related tasks should be conducted using approved tools and platforms. Employees must maintain a professional work environment and ensure their internet connection is stable for smooth workflow.</p>"], "title": ["None", "Work Policy"], "is_active": ["None", "True"], "created_at": ["None", "2024-09-21 05:30:17.901000"], "created_by": ["None", "1"], "modified_by": ["None", "1"], "is_visible_to_all": ["None", "True"]}', '2026-02-23 12:19:24.037467+05:30', NULL, 58, '127.0.0.1', NULL, NULL, NULL, '', NULL, NULL);
