INSERT INTO public.auditlog_logentry VALUES (1139, '6', 6, 'Policy object (6)', 0, '{"id": ["None", "6"], "body": ["None", "<h3 style=\"text-align: center; \"><strong>IT Support Policy</strong></h3><p><strong>Purpose:</strong><br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; To provide employees with guidelines for receiving technical support.</p><p><strong>Body:</strong><br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Employees encountering technical issues must submit a support ticket through the companyÆs IT service desk. Priority will be given to high-impact issues that affect business operations. IT support staff will resolve issues within a specified time frame based on severity. Employees are encouraged to check for common solutions in the knowledge base before requesting support. Any hardware issues with company devices should also be reported to IT for troubleshooting or replacement.</p>"], "title": ["None", "Support Policy"], "is_active": ["None", "True"], "created_at": ["None", "2024-09-21 05:33:13.689000"], "created_by": ["None", "1"], "modified_by": ["None", "1"], "is_visible_to_all": ["None", "True"]}', '2026-02-23 12:19:24.045493+05:30', NULL, 58, '127.0.0.1', NULL, NULL, NULL, '', NULL, NULL);
