INSERT INTO public.auditlog_logentry VALUES (1143, '8', 8, 'Policy object (8)', 0, '{"id": ["None", "8"], "body": ["None", "<h3 style=\"text-align: center; \"><strong>Software Use Policy</strong></h3><p><strong>Purpose:</strong><br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; To regulate the usage of licensed software and prevent the use of unauthorized programs.</p><p><strong>Body:</strong><br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Employees must use only company-approved and licensed software for work purposes. The installation of personal or unauthorized software on company systems is prohibited and may result in disciplinary action. IT regularly audits all company devices to ensure compliance. If employees require additional software, they must submit a request to the IT department for approval.</p>"], "title": ["None", "Software Policy"], "is_active": ["None", "True"], "created_at": ["None", "2024-09-21 05:34:56.573000"], "created_by": ["None", "1"], "modified_by": ["None", "1"], "is_visible_to_all": ["None", "True"]}', '2026-02-23 12:19:24.050882+05:30', NULL, 58, '127.0.0.1', NULL, NULL, NULL, '', NULL, NULL);
