INSERT INTO public.auditlog_logentry VALUES (1145, '9', 9, 'Policy object (9)', 0, '{"id": ["None", "9"], "body": ["None", "<h3 style=\"text-align: center; \"><strong>Internet Usage Policy</strong></h3><p><strong>Purpose:</strong><br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;To manage the appropriate use of the companyÆs internet and network resources.</p><p><strong>Body:</strong><br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Employees are expected to use the companyÆs internet resources primarily for work-related activities. Access to social media, streaming services, and non-work-related websites should be limited during working hours unless part of the employee''s job. Monitoring systems are in place to track internet usage, and any misuse of company bandwidth may result in restricted access. Downloading unauthorized files or software from the internet is strictly prohibited.</p>"], "title": ["None", "Internet Policy"], "is_active": ["None", "True"], "created_at": ["None", "2024-09-21 05:35:37.592000"], "created_by": ["None", "1"], "modified_by": ["None", "1"], "is_visible_to_all": ["None", "True"]}', '2026-02-23 12:19:24.05346+05:30', NULL, 58, '127.0.0.1', NULL, NULL, NULL, '', NULL, NULL);
