INSERT INTO public.auditlog_logentry VALUES (2228, '1', 1, 'Recruitment Drive', 0, '{"id": ["None", "1"], "title": ["None", "Recruitment Drive"], "closed": ["None", "False"], "resume": ["None", "recruitment.Resume.None"], "vacancy": ["None", "15"], "end_date": ["None", "2025-07-30"], "candidate": ["None", "recruitment.Candidate.None"], "is_active": ["None", "True"], "stage_set": ["None", "recruitment.Stage.None"], "company_id": ["None", "1"], "created_at": ["None", "2025-07-22 08:48:40.136000"], "created_by": ["None", "1"], "start_date": ["None", "2025-07-01"], "description": ["None", "<p><b><u><span style=\"font-size: 18px;\">Position: Django Developer &amp; ODOO dev</span></u></b></p><p><b>Job Description:</b></p><p>We are seeking a skilled Django Developers and ODOO developers to join our dynamic team. The ideal candidate will have a strong background in web development with a focus on the Django framework. You will be responsible for designing, building, and maintaining high-performance web applications that are scalable and secure.</p><p><b>Key Responsibilities:</b></p><p>Develop and maintain web applications using Django.</p><p>Write clean, maintainable, and efficient code.</p><p>Design and implement robust APIs.</p><p>Collaborate with front-end developers to integrate user-facing elements.</p><p>Optimize applications for maximum speed and scalability.</p><p>Participate in code reviews to maintain code quality and share knowledge.</p><p>Stay updated with the latest industry trends and technologies.</p><p><b>Requirements:</b></p><p>Proven experience as a Django Developer.</p><p>Proficient in Python and Django framework.</p><p>Familiarity with front-end technologies (JavaScript, HTML5, CSS3).</p><p>Experience with relational databases (PostgreSQL, MySQL).</p><p>Knowledge of version control systems (Git).</p><p>Understanding of RESTful APIs and web services.</p><p>Strong problem-solving skills and attention to detail.</p><p>Excellent communication and teamwork skills.</p><p>BachelorÆs degree in Computer Science, Engineering, or a related field.</p><p><b>Preferred Qualifications:</b></p><p>Experience with cloud platforms (AWS, Azure, GCP).</p><p>Knowledge of containerization and orchestration (Docker, Kubernetes).</p><p>Familiarity with Agile development methodologies.</p>"], "modified_by": ["None", "1"], "is_published": ["None", "True"], "is_event_based": ["None", "False"], "job_position_id": ["None", "None"], "optional_resume": ["None", "False"], "onboarding_stage": ["None", "onboarding.OnboardingStage.None"], "linkedin_account_id": ["None", "None"], "publish_in_linkedin": ["None", "True"], "optional_profile_image": ["None", "False"]}', '2026-02-23 12:19:25.047629+05:30', NULL, 68, '127.0.0.1', NULL, NULL, NULL, '', NULL, NULL);
