INSERT INTO public.base_announcement VALUES (1, '2025-07-17 16:04:52.749+05:30', true, 'Fits Tour', '<h1 class="hr-heading hr-heading--h1 hr-hero__title" style="-webkit-font-smoothing: auto; font-size: 5rem; margin-right: auto; margin-bottom: 0px; margin-left: auto; font-family: Poppins, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif; font-weight: bold; text-align: center; max-width: 855px; line-height: 96px; color: rgb(28, 28, 28);">The&nbsp;<span class="hr-hero__highlight" style="-webkit-font-smoothing: auto; position: relative;">only</span>&nbsp;HR Software You''ll ever need.</h1><p class="hr-hero__lead" style="-webkit-font-smoothing: auto; font-size: 1.25rem; color: rgb(28, 28, 28); max-width: 650px; text-align: center; margin: 1rem auto 1.5rem; font-family: &quot;Open Sans&quot;, Inter, &quot;Helvetica Neue Light&quot;, &quot;Helvetica Neue&quot;, Helvetica, Arial, sans-serif;">Fits HRMS offers all the features you would expect from your favorite Open Source HR Software and much more.<span style="-webkit-font-smoothing: auto; font-weight: bolder;"><br style="-webkit-font-smoothing: auto;">It''s free &amp; open-source!</span></p>', '2100-12-17', false, true, 1, 1);
