INSERT INTO public.base_fitsmailtemplate VALUES (1, '2025-07-05 15:09:13.733+05:30', true, 'Offer letter', '<p style="font-size: 12.8px; text-align: center;"><span style="font-weight: bolder;"><span style="font-family: &quot;Courier New&quot;; font-size: 24px;">Congratulations! Job Offer at {{instance.get_company}}</span></span></p><p style="font-size: 12.8px;">username:{{instance.get_email}}</p><p style="font-size: 12.8px;">password:{{instance.phone}}</p><p style="font-size: 12.8px;"><i><span style="font-size: 14px;">Dear {{instance.get_full_name}},</span></i></p><p style="font-size: 12.8px;">&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; I am delighted to extend an official offer of employment to you for the position of [Job Title] at [Company Name]. We were thoroughly impressed with your skills, experience, and the passion you demonstrated during the interview process.</p><p style="font-size: 12.8px;"><span style="font-size: 12.8px;">Here are the details of your job offer:&nbsp;</span></p><p style="font-size: 12.8px;"><span style="font-size: 12.8px;">&nbsp; &nbsp; Job Position: {{instance.get_job_position}}</span></p><p style="font-size: 12.8px;"><span style="font-size: 12.8px;">We believe that your unique talents will make a significant contribution to our team, and we are thrilled about the prospect of you joining us. Please take the time to review the attached detailed job description, as well as the terms and conditions outlined in the employment contract.</span><br></p><p style="font-size: 12.8px;"><span style="font-size: 12.8px;">To signify your acceptance of this job offer, please confirm your agreement by [Date to Respond]. If you have any questions or need further clarification, feel free to contact me directly</span><br></p><p style="font-size: 12.8px;"><span style="font-size: 12.8px;">We are excited about the value you will bring to [Company Name], and we eagerly anticipate the positive impact you''ll have on our team.</span><br></p><p style="font-size: 12.8px;"><span style="font-size: 12.8px;">Welcome aboard, and we look forward to a successful and fulfilling working relationship!</span><br></p><p style="font-size: 12.8px;"><span style="font-size: 12.8px;">Warm regards,</span></p>', NULL, NULL, NULL);
INSERT INTO public.base_fitsmailtemplate VALUES (2, '2025-07-12 15:53:52.188+05:30', false, 'Leave Request Mail', '<p>Dear,</p><p>This is to inform you that {{ model_instance.employee_id }} has submitted a leave request for {{model_instance.requested_days}} days. Please take the necessary actions to review and process the request at your earliest convenience.<br><br>If you require any additional information or updates, feel free to communicate directly with {{ model_instance.employee_id }}.<br><br>Thank you for your prompt attention to this matter.</p>', 1, 1, 1);
