INSERT INTO public.helpdesk_faq VALUES (1, '2025-07-12 08:49:37.597+05:30', true, 'How to create a leave request?', 'Click on My Leave Request > Select Leave Type > Fill out the form', 1, NULL, NULL, NULL);
INSERT INTO public.helpdesk_faq VALUES (2, '2025-07-12 08:49:38.034+05:30', true, 'How to export work records?', 'Click on Work Records inside Attendance, filter the data and click on Export button', 2, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (3, '2025-07-12 08:49:38.147+05:30', true, 'How to create a shift request?', 'go to employee --> shift request --> create --> Fill out the form', 4, NULL, NULL, NULL);
INSERT INTO public.helpdesk_faq VALUES (4, '2025-07-12 08:49:38.278+05:30', true, 'How to add stage managers to an existing stage?', 'Recruitment --> Stage 3 dot --> Edit --> Managers', 5, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (5, '2025-07-12 08:49:38.394+05:30', true, 'What is recruitment pipeline?', 'All the details about the recruitment, stage, and candidate can be controlled from here.', 5, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (6, '2025-07-12 08:49:38.503+05:30', true, 'How to create an Employee?', 'Employee > Employees > Create > Fill out the form', 3, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (7, '2025-07-12 08:56:34.988+05:30', true, 'How to assign leave type to employee', 'Leave > Assigned Leave > Assign', 1, NULL, 1, 1);
INSERT INTO public.helpdesk_faq VALUES (8, '2025-07-12 09:01:56.975+05:30', true, 'How to create leave types', 'Leave > Leave Types > Create > Fill Out Form', 1, NULL, 1, 1);
INSERT INTO public.helpdesk_faq VALUES (9, '2025-07-12 09:15:00+05:30', true, 'What is the Attendance Module used for?', 'The Attendance Module tracks and manages employee attendance, including check-ins, check-outs, and biometric integration.', 2, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (10, '2025-07-12 09:15:00+05:30', true, 'What is the Check-In/Check-Out system?', 'It records employee working hours by tracking their check-in and check-out times.', 2, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (11, '2025-07-12 09:15:00+05:30', true, 'What is the purpose of Biometric Devices?', 'Biometric devices, such as ZKTeco,Matrix COSEC & Anviz synchronize attendance data automatically for accurate tracking.', 2, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (12, '2025-07-12 09:15:00+05:30', true, 'How can employees edit their attendance records?', 'Employees can submit an Attendance Request to edit or add missing attendance records.', 2, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (13, '2025-07-12 09:15:00+05:30', true, 'What is the Hour Account feature?', 'It tracks total worked hours for employees by month and year.', 2, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (14, '2025-07-12 09:15:00+05:30', true, 'What does the Work Records feature do?', 'It compiles daily attendance statuses (e.g., present, absent) into monthly records.', 2, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (15, '2025-07-12 09:15:00+05:30', true, 'What is Attendance Activity?', 'It shows attendance records generated from check-ins, check-outs, or biometric devices.', 2, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (16, '2025-07-12 09:15:00+05:30', true, 'What does Late Come Early Out mean?', 'It flags employees who check in late or leave early based on their shift schedule.', 2, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (17, '2025-07-12 09:15:00+05:30', true, 'What can employees see in My Attendance?', 'Employees can view their previous attendance records and statuses.', 2, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (18, '2025-07-12 09:15:00+05:30', true, 'What are Attendance Requests?', 'They allow employees to request modifications to attendance records if errors occur.', 2, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (19, '2025-07-12 09:30:00+05:30', true, 'What is the Employee Profile view used for?', 'The Employee Profile view displays all details about an employee, including personal, work, bank information, and more. It also allows employees to customize visible tabs.', 3, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (20, '2025-07-12 09:30:00+05:30', true, 'How can an employee request a shift change?', 'Employees can request a shift change through the ''Reallocate Shift'' option in the Work Type & Shift tab. Admin approval is required for changes.', 3, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (21, '2025-07-12 09:30:00+05:30', true, 'What details can employees view in the Attendance tab?', 'The Attendance tab shows all attendance records for the employee in a detailed tabular view.', 3, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (22, '2025-07-12 09:30:00+05:30', true, 'What actions are available in the Employee Directory?', 'The Employee Directory allows actions like importing, exporting, bulk archiving, unarchiving, updating, and deleting employee data.', 3, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (23, '2025-07-12 09:30:00+05:30', true, 'How are document requests handled?', 'Admins or managers create document requests specifying details like title, format, and size. Employees upload documents directly from their profile.', 3, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (24, '2025-07-12 09:30:00+05:30', true, 'What is the Shift Request feature?', 'The Shift Request feature allows employees to request temporary or permanent shift changes. Approval by a manager or admin is required.', 3, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (25, '2025-07-12 09:30:00+05:30', true, 'What is a Rotating Work Type Assign?', 'A Rotating Work Type Assign automates frequent changes in work types based on conditions like intervals, weekends, or specific dates.', 3, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (26, '2025-07-12 09:30:00+05:30', true, 'How can employees manage disciplinary actions?', 'Admins can create disciplinary actions like warnings or suspensions, and these may block employee logins for the specified period.', 3, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (27, '2025-07-12 09:30:00+05:30', true, 'What can employees find in the Policies section?', 'Employees can access company policies and guidelines in the Policies section for reference.', 3, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (28, '2025-07-12 09:30:00+05:30', true, 'What is the Organization Chart feature?', 'The Organization Chart provides a visual representation of reporting structures, helping to identify team members and managers.', 3, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (29, '2025-07-12 09:30:00+05:30', true, 'What is the Recruitment module in Fits HRMS?', 'The Recruitment module allows HR professionals to create and manage job postings, receive and review resumes, manage interviews, and track candidate progress throughout the hiring process.', 5, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (30, '2025-07-12 09:30:00+05:30', true, 'What is the Recruitment Pipeline feature?', 'The Recruitment Pipeline is a comprehensive feature that organizes candidates through various stages using tabular and Kanban views. It supports multiple recruitment drives, each represented as a tab for easy management.', 5, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (31, '2025-07-12 09:30:00+05:30', true, 'How can I create a new recruitment in Fits?', 'To create a new recruitment, click on the ''+ Create'' button from Recruitment > Recruitments , specify the job position, description, vacancies, managers, start and end dates, and select a recruitment survey.', 5, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (32, '2025-07-12 09:30:00+05:30', true, 'What are the main stage types in the recruitment process?', 'The main stage types are Initial, Interview, Hired, and Cancelled. Each type serves a specific purpose, such as automatically registering candidates or marking them as hired.', 5, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (33, '2025-07-12 09:30:00+05:30', true, 'How do I add a new stage to the recruitment process?', 'To add a new stage, click on the ''+ Stage'' button from Recruitment Pipeline, provide the stage title, assign stage managers, and specify the stage type (e.g., Initial, Interview, Hired).', 5, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (34, '2025-07-12 09:30:00+05:30', true, 'What is Resume Shortlisting and how does it work?', 'Resume Shortlisting is a feature that uses skill-based keyword optimization to rank resumes. The system calculates scores for each resume based on matching skills and displays them in descending order.', 5, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (35, '2025-07-12 09:30:00+05:30', true, 'What is the Skill Zone feature?', 'The Skill Zone categorizes candidates based on their skills, helping recruiters match them to relevant job positions more efficiently.', 5, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (36, '2025-07-12 09:30:00+05:30', true, 'How can I manage interviews within the Recruitment module?', 'You can manage interviews through the ''Scheduled Interviews'' page, where you can add, edit, or delete interviews, assign interviewers, and track the status of interviews.', 5, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (37, '2025-07-12 09:30:00+05:30', true, 'Can I customize application forms in Fits HRMS?', 'Yes, the Recruitment Survey feature allows HR managers to create custom questionnaires for candidates, which are integrated into the application forms.', 5, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (38, '2025-07-12 09:30:00+05:30', true, 'What are the available views for managing candidates?', 'Candidates can be managed using the Kanban view, list view, and detailed view. These views allow for filtering, grouping, and performing actions like editing, exporting, or converting candidates to employees.', 5, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (39, '2025-07-12 09:30:00+05:30', true, 'What is the Payroll module in Fits HRMS?', 'The Payroll module in Fits HRMS enables businesses to manage employee allowances, deductions, taxes, and generate accurate payslips, ensuring streamlined and efficient payroll processes.', 6, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (40, '2025-07-12 09:30:00+05:30', true, 'What features does the Payroll Dashboard offer?', 'The Payroll Dashboard provides visual insights into payroll processes, including charts for payslips, contract details, and department-wise payslips. Managers can also download data as Excel files.', 6, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (41, '2025-07-12 09:30:00+05:30', true, 'How does Contract Management work in Fits?', 'Contract Management allows users to create contracts, define compensation, set contract duration, and manage leave settings. It supports various wage types for customized work arrangements.', 6, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (42, '2025-07-12 09:30:00+05:30', true, 'What is the Allowance Management feature?', 'Allowance Management enables users to create and customize allowances, set eligibility conditions, and specify fixed or variable allowances. It simplifies targeting allowances to employee groups and ensures fairness.', 6, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (43, '2025-07-12 09:30:00+05:30', true, 'How are deductions managed in Fits?', 'The Deduction Management feature allows users to create and personalize deductions, set eligibility conditions, and choose fixed or variable amounts. It ensures streamlined deductions and fair practices.', 6, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (44, '2025-07-12 09:30:00+05:30', true, 'What is the Loan and Advance Salary module?', 'This module helps manage employee loans, installments, and advance salary transactions, ensuring accurate and transparent financial dealings.', 6, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (45, '2025-07-12 09:30:00+05:30', true, 'What does the Encashments & Reimbursements feature offer?', 'This feature supports reimbursements for company-related expenses, leave encashments, and bonus point encashments, simplifying the process for diverse employee needs.', 6, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (46, '2025-07-12 09:30:00+05:30', true, 'How does the Federal Tax feature work?', 'The Federal Tax feature automates tax calculations, defines tax brackets, and sets rates based on income. It ensures compliance and smooth payroll processing.', 6, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (47, '2025-07-12 09:30:00+05:30', true, 'How are payslips generated in Fits?', 'The Payslip Generation feature calculates salaries, including allowances, deductions, and taxes, and creates accurate and detailed payslips for each pay period.', 6, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (48, '2025-07-12 09:30:00+05:30', true, 'What is the Asset Management System in Fits HRMS?', 'The Asset Management System enables employees to request and manage work-related assets like computers and equipment. It categorizes assets, tracks requests, and ensures efficient allocation.', 7, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (49, '2025-07-12 09:30:00+05:30', true, 'What features are available on the Asset Dashboard?', 'The Asset Dashboard displays the total number of assets, asset requests, and assets in use. It includes pie charts and tables for asset allocation and provides tools for admins to approve requests and allocate assets directly.', 7, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (50, '2025-07-12 09:30:00+05:30', true, 'How can admin search for assets in Fits HRMS?', 'Admin can search for specific asset categories or individual assets using the search bar. The system dynamically filters results based on the search term.', 7, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (51, '2025-07-12 09:30:00+05:30', true, 'What is the Asset Import feature?', 'The Asset Import feature allows admin to upload large amounts of asset data, such as names, purchase dates, and categories, from an external file like Excel, improving efficiency in asset management.', 7, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (52, '2025-07-12 09:30:00+05:30', true, 'What is the purpose of the Asset Export feature?', 'The Asset Export feature enables admin to download asset data, either filtered or in full, for reporting or further processing.', 7, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (53, '2025-07-12 09:30:00+05:30', true, 'How can asset categories be managed in Fits HRMS?', 'Admin can create, update, and delete asset categories. Categories can only be deleted if they are empty, ensuring no associated assets remain in use.', 7, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (54, '2025-07-12 09:30:00+05:30', true, 'What is the Asset Request and Allocation feature?', 'This feature allows employees to request new assets or return allocated ones, while admins can allocate or reallocate assets based on requests and availability.', 7, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (55, '2025-07-12 09:30:00+05:30', true, 'What details can be updated in the Asset Updation form?', 'Admin can update details like asset name, description, tracking ID, purchase date, cost, status, and expiry date. Notifications can also be set for upcoming expiry dates.', 7, NULL, NULL, 1);
INSERT INTO public.helpdesk_faq VALUES (56, '2025-07-12 09:30:00+05:30', true, 'How does Asset History tracking work?', 'The Asset History feature tracks details of returned assets, allowing admin to filter, group, and sort asset usage data as needed.', 7, NULL, NULL, 1);
