INSERT INTO public.offboarding_resignationletter VALUES (1, '2025-07-15 09:15:33.566+05:30', true, 'Resignation', '<p>After much consideration, I have decided to pursue a new opportunity that aligns with my career goals and personal aspirations. Working at Fits has been an incredibly rewarding experience, and I deeply appreciate the support, guidance, and opportunities for growth provided by the company and my colleagues.</p><p>I am committed to ensuring a smooth transition and will do my best to complete my ongoing tasks and assist in handing over responsibilities. Please let me know how I can support the transition process.</p><p>I want to express my gratitude to the entire team at Fits for the collaboration, learning, and support throughout my time here. I will cherish the experience and the relationships I have built.</p><p>Thank you once again for the opportunity to be a part of Fits, and I wish the company continued success in the future.</p>', '2025-07-30', 'requested', 13, 12, 13, NULL);
INSERT INTO public.offboarding_resignationletter VALUES (2, '2025-07-15 09:16:37.925+05:30', true, 'Resignation Letter', '<p>This was not an easy decision, but after careful thought, I believe it is the right time for me to explore new professional challenges. My time at Fits has been an enriching journey, and I am truly grateful for the opportunities I have had to contribute and grow, both professionally and personally.</p><p>I will do my best to ensure a smooth transition and am happy to assist in handing over my current projects or training a replacement if necessary. Please feel free to guide me on how I can assist during this period.</p><p>Thank you once again for the support and for allowing me to be part of such a fantastic team. I wish Fits continued growth and success, and I look forward to staying connected in the future.</p>', '2025-07-30', 'requested', 29, 28, 29, NULL);
INSERT INTO public.recruitment_recruitment VALUES (1, '2025-07-22 14:18:40.136+05:30', true, 'Recruitment Drive', '<p><b><u><span style="font-size: 18px;">Position: Django Developer &amp; ODOO dev</span></u></b></p><p><b>Job Description:</b></p><p>We are seeking a skilled Django Developers and ODOO developers to join our dynamic team. The ideal candidate will have a strong background in web development with a focus on the Django framework. You will be responsible for designing, building, and maintaining high-performance web applications that are scalable and secure.</p><p><b>Key Responsibilities:</b></p><p>Develop and maintain web applications using Django.</p><p>Write clean, maintainable, and efficient code.</p><p>Design and implement robust APIs.</p><p>Collaborate with front-end developers to integrate user-facing elements.</p><p>Optimize applications for maximum speed and scalability.</p><p>Participate in code reviews to maintain code quality and share knowledge.</p><p>Stay updated with the latest industry trends and technologies.</p><p><b>Requirements:</b></p><p>Proven experience as a Django Developer.</p><p>Proficient in Python and Django framework.</p><p>Familiarity with front-end technologies (JavaScript, HTML5, CSS3).</p><p>Experience with relational databases (PostgreSQL, MySQL).</p><p>Knowledge of version control systems (Git).</p><p>Understanding of RESTful APIs and web services.</p><p>Strong problem-solving skills and attention to detail.</p><p>Excellent communication and teamwork skills.</p><p>BachelorÆs degree in Computer Science, Engineering, or a related field.</p><p><b>Preferred Qualifications:</b></p><p>Experience with cloud platforms (AWS, Azure, GCP).</p><p>Knowledge of containerization and orchestration (Docker, Kubernetes).</p><p>Familiarity with Agile development methodologies.</p>', false, false, true, 15, '2025-07-01', '2025-07-30', NULL, true, false, false, 1, 1, NULL, NULL, 1);
INSERT INTO public.recruitment_recruitment VALUES (2, '2025-07-22 14:25:43.899+05:30', true, 'FutureForce Recruitment', '<p>We are looking for a motivated and dynamic <b>Salesman</b> to join our team. The ideal candidate will have a passion for <b>sales, excellent communication skills, and a knack for building relationships with customers</b>. You will play a key role in driving our business growth by meeting sales targets and providing outstanding customer service.<br></p>', false, false, true, 10, '2025-07-01', '2025-07-30', NULL, true, false, false, 1, 1, NULL, NULL, 1);
INSERT INTO public.recruitment_recruitment VALUES (3, '2025-07-22 14:33:26.892+05:30', true, 'Hiring Employees', '<p>We are seeking a skilled Django Developer to join our dynamic team. The ideal candidate will have a strong background in web development with a focus on the Django framework. You will be responsible for designing, building, and maintaining high-performance web applications that are scalable and secure.<br></p>', false, true, true, 5, '2025-07-01', '2025-07-30', NULL, true, false, false, NULL, 1, NULL, NULL, 1);
